package in.aicon.pocket;
import android.graphics.*;import android.database.Cursor;import java.io.*;import java.util.*;
/** Original paginated raster PDF. Canvas handles script shaping and fallback fonts;
 * JPEG pages are embedded directly. Not a searchable-text or restore format. */
final class LedgerPdf implements AutoCloseable {
 final java.util.List<byte[]> images=new ArrayList<>();Bitmap bitmap;Canvas canvas;Paint paint=new Paint(3);int number;float y;String header;
 LedgerPdf(String header){this.header=header;next();}
 void finishPage(){if(bitmap==null)return;ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,88,out);images.add(out.toByteArray());bitmap.recycle();bitmap=null;if(images.size()>150)throw new IllegalArgumentException("Statement too long for PDF. Use CSV export for this ledger.");}
 void next(){finishPage();number++;bitmap=Bitmap.createBitmap(1190,1684,Bitmap.Config.ARGB_8888);canvas=new Canvas(bitmap);canvas.scale(2,2);canvas.drawColor(Color.WHITE);paint.setColor(0xff123c36);paint.setTypeface(Typeface.create("sans-serif-medium",0));paint.setTextSize(23);canvas.drawText("Hisab",40,45,paint);paint.setColor(0xff31443f);paint.setTextSize(10);canvas.drawText("Private ledger statement | "+header+" | Page "+number,40,66,paint);canvas.drawLine(40,76,555,76,paint);y=98;}
 void line(String text){paint.setTypeface(Typeface.create("sans-serif",0));paint.setTextSize(10);paint.setColor(0xff182a26);String remaining=text==null?"":text.replaceAll("[\\r\\n\\t]"," ");if(remaining.isEmpty()){y+=8;return;}while(!remaining.isEmpty()){int end=paint.breakText(remaining,true,510,null);if(end<1)end=1;if(end<remaining.length()){int space=remaining.lastIndexOf(' ',end);if(space>0)end=space;}if(y>792)next();canvas.drawText(remaining.substring(0,end),40,y,paint);y+=15;remaining=remaining.substring(end).trim();}}
 static void ascii(ByteArrayOutputStream out,String text)throws IOException{out.write(text.getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 byte[] bytes()throws Exception{finishPage();ByteArrayOutputStream out=new ByteArrayOutputStream();ascii(out,"%PDF-1.4\n");int objects=2+images.size()*3;long[] offsets=new long[objects+1];for(int id=1;id<=objects;id++){offsets[id]=out.size();ascii(out,id+" 0 obj\n");if(id==1)ascii(out,"<< /Type /Catalog /Pages 2 0 R >>\n");else if(id==2){StringBuilder kids=new StringBuilder();for(int p=0;p<images.size();p++)kids.append(3+p*3).append(" 0 R ");ascii(out,"<< /Type /Pages /Count "+images.size()+" /Kids ["+kids+"] >>\n");}else{int page=(id-3)/3,part=(id-3)%3,base=3+page*3;if(part==0)ascii(out,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /I "+(base+2)+" 0 R >> >> /Contents "+(base+1)+" 0 R >>\n");else if(part==1){String stream="q 595 0 0 842 0 0 cm /I Do Q\n";ascii(out,"<< /Length "+stream.length()+" >>\nstream\n"+stream+"endstream\n");}else{byte[] image=images.get(page);ascii(out,"<< /Type /XObject /Subtype /Image /Width 1190 /Height 1684 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length "+image.length+" >>\nstream\n");out.write(image);ascii(out,"\nendstream\n");}}ascii(out,"endobj\n");if(out.size()>16*1024*1024)throw new IllegalArgumentException("PDF is too large. Use CSV export for this ledger.");}long xref=out.size();ascii(out,"xref\n0 "+(objects+1)+"\n0000000000 65535 f \n");for(int i=1;i<=objects;i++)ascii(out,String.format(Locale.ROOT,"%010d 00000 n \n",offsets[i]));ascii(out,"trailer\n<< /Size "+(objects+1)+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF\n");return out.toByteArray();}
 @Override public void close(){if(bitmap!=null){bitmap.recycle();bitmap=null;}images.clear();}
 static byte[] create(QuickActivity a)throws Exception{try(LedgerPdf p=new LedgerPdf(a.today())){p.line("Ledger: "+a.ledgerLabel());p.line("Currency: "+a.settings.get("currency")+". Manual records; not a bank statement.");p.line("Month: "+a.viewedMonth()+" | Income: "+a.ru(a.viewedTotal("income"))+" | Expenses: "+a.ru(a.viewedTotal("expense")));p.line("Loans and transfers are excluded from income/expense totals. All entries follow.");p.line("");try(Cursor c=a.db.rawQuery("SELECT day,kind,amount,account,category,note,person,uuid FROM tx ORDER BY day,id",null)){while(c.moveToNext()){if(p.y>690)p.next();p.line(c.getString(0)+" | "+c.getString(1)+" | "+a.ru(c.getLong(2))+" | "+c.getString(3));p.line("Category: "+c.getString(4)+(c.getString(6).isEmpty()?"":" | Person: "+c.getString(6)));if(!c.getString(5).isEmpty())p.line("Note: "+c.getString(5));String due=DuePlans.get(a,DuePlans.key(a.profileKey(),c.getString(7))).optString("date","");if(!due.isEmpty())p.line("Recorded pay-by date: "+due+" (your note, not confirmation by the other person)");p.line("");}}return p.bytes();}}
}
